module PaperBooleanRelease310Tests =
    let private unwrap value = value |> Result.defaultWith (failwithf "%A")
    let private p x y = Point.create (x*1.0<length>) (y*1.0<length>)
    let private check actual expected =
        let want=abs(float(Area.signedPath expected))
        Assert.True(abs(abs(float(Area.signedPath actual))-want)<=1e-5*max 1.0 want)
        for source,target in [actual,expected;expected,actual] do
            for subpath in Path.subpaths source do
                Assert.True(Subpath.isClosed subpath)
                for segment in Subpath.segments subpath do
                    for t in [0.0;0.25;0.5;0.75;1.0] do
                        let point=Segment.point segment (t*1.0<parameter>) |> unwrap
                        let distance=Distance.pathDistance target point |> unwrap
                        Assert.True(distance<=0.001<length>,sprintf "Boundary distance %A" distance)

    [<Fact>]
    let ``Paper Boolean fixture 79 geometry`` () =
        let left = Path.ofSubpaths [
                ([CubicBezier(p 923.0174999999999 265.80499999999995,p 944.3699999999999 289.30999999999995,p 956.29 320.10999999999996,p 956.29 351.86999999999995);
                    CubicBezier(p 956.29 351.86999999999995,p 956.29 383.6574999999999,p 944.3499999999999 414.48499999999996,p 922.9625 437.99499999999995);
                    CubicBezier(p 922.9625 437.99499999999995,p 922.9625 437.99499999999995,p 911.15 427.24499999999995,p 911.15 427.24499999999995);
                    CubicBezier(p 911.15 427.24499999999995,p 929.95 406.5775,p 940.29 379.80749999999995,p 940.29 351.86999999999995);
                    CubicBezier(p 940.29 351.86999999999995,p 940.29 323.9625,p 929.97 297.2149999999999,p 911.2025 276.55499999999995);
                    CubicBezier(p 911.2025 276.55499999999995,p 911.2025 276.55499999999995,p 923.0174999999999 265.80499999999995,p 923.0174999999999 265.80499999999995)] |> Subpath.create |> unwrap |> Subpath.close |> unwrap)]
        let right = Path.ofSubpaths [
                ([CubicBezier(p 940.29 351.92499999999995,p 940.29 351.92499999999995,p 956.29 351.92499999999995,p 956.29 351.92499999999995);
                    CubicBezier(p 956.29 351.92499999999995,p 956.275 383.69249999999994,p 944.3375 414.49999999999994,p 922.9625 437.99499999999995);
                    CubicBezier(p 922.9625 437.99499999999995,p 922.9625 437.99499999999995,p 911.15 427.24499999999995,p 911.15 427.24499999999995);
                    CubicBezier(p 911.15 427.24499999999995,p 929.9375 406.5925,p 940.275 379.8449999999999,p 940.29 351.92499999999995)] |> Subpath.create |> unwrap |> Subpath.close |> unwrap)]
        let actual = Csg.unionPath left right Nonzero |> unwrap
        let expected = Parse.path "M923.0175,265.805c21.3525,23.505 33.2725,54.305 33.2725,86.065c0,0.01833 0,0.03667 -0.00001,0.055h0.00001c-0.00005,0.10258 -0.00022,0.20515 -0.00052,0.3077c-0.06338,22.18242 -5.9393,43.88534 -16.78017,62.94682c-4.63138,8.14369 -10.16899,15.8051 -16.54682,22.81548l-11.8125,-10.75c8.97181,-9.86302 16.01692,-21.11585 20.93099,-33.22212c5.34364,-13.16533 8.16725,-27.34044 8.20856,-41.83592c0.0003,-0.10564 0.00044,-0.21129 0.00044,-0.31697c0,-27.9075 -10.32,-54.655 -29.0875,-75.315z" |> unwrap
